 public enum TransactionStatus { Started,Committed,RolledBack }
 public class FailureHandlingOptions { public FailureHandlingOptions SetFailuresPreprocessor(object p){return this;}public FailureHandlingOptions SetClearAfterRollback(bool x){return this;} }
 public class Transaction:IDisposable { Document d;TransactionStatus status;public Transaction(Document doc,string name){d=doc;}public TransactionStatus Start(){return status=TransactionStatus.Started;}public FailureHandlingOptions GetFailureHandlingOptions(){return new FailureHandlingOptions();}public void SetFailureHandlingOptions(FailureHandlingOptions x){}public TransactionStatus Commit(){if(d.DriftOnCommit){var e=d.Elements.Values.First(x=>x.Parameters.Count>0);e.Parameters[0].Value="commit-drift";}return status=TransactionStatus.Committed;}public TransactionStatus GetStatus(){return status;}public TransactionStatus RollBack(){return status=TransactionStatus.RolledBack;}public void Dispose(){} }
 public class TransactionGroup:IDisposable { Document d;TransactionStatus status;Dictionary<Parameter,Tuple<bool,object>> before;public TransactionGroup(Document doc,string name){d=doc;}public TransactionStatus Start(){before=d.Elements.Values.SelectMany(x=>x.Parameters).ToDictionary(x=>x,x=>Tuple.Create(x.HasValue,x.Value));return status=TransactionStatus.Started;}public TransactionStatus Assimilate(){return status=TransactionStatus.Committed;}public TransactionStatus RollBack(){if(d.RollbackThrows)throw new InvalidOperationException("rollback failure");if(d.RollbackWrongStatus)return status=TransactionStatus.Committed;foreach(var x in before){x.Key.HasValue=x.Value.Item1;x.Key.Value=x.Value.Item2;}if(d.RollbackDrifts)d.Elements[100].Parameters[0].Value="bad-rollback";return status=TransactionStatus.RolledBack;}public TransactionStatus GetStatus(){return status;}public void Dispose(){} }
 public class FilteredElementCollector:IDisposable,IEnumerable<Element> { Document d;BuiltInCategory category;public FilteredElementCollector(Document d){this.d=d;}public FilteredElementCollector OfCategory(BuiltInCategory c){category=c;return this;}public FilteredElementCollector WhereElementIsNotElementType(){return this;}public IEnumerator<Element> GetEnumerator(){return d.Elements.Values.Where(e=>!(e is ElementType)&&e.Category!=null&&e.Category.Id.Value==(long)category).GetEnumerator();}IEnumerator IEnumerable.GetEnumerator(){return GetEnumerator();}public void Dispose(){} }
