 internal static class NativeModelQueries { internal class ReadBudget { public int Scanned;public ReadBudget(int max){}public void Scan(){if(++Scanned>20000)throw new InvalidOperationException("scan budget");}public void Reserve(object o){} }public static string SignedId(ElementId id){return id.Value.ToString();} public static long ExactId(Dictionary<string,object>a,string key){return Convert.ToInt64(a[key]);}public static long ExactSignedId(Dictionary<string,object>a,string key){return Convert.ToInt64(a[key]);} }
 internal static partial class WorkbenchActions {
  static Element RequiredElement(Document d,long id){Element e;if(!d.Elements.TryGetValue(id,out e))throw new InvalidOperationException("missing");return e;}
  static Parameter ResolveInstanceParameter(Document d,long id,long pid,out Element owner){owner=RequiredElement(d,id);var matches=owner.Parameters.Where(x=>x.Id.Value==pid).ToArray();if(matches.Length!=1||matches[0].IsReadOnly||!Object.ReferenceEquals(matches[0].Element,owner))throw new InvalidOperationException("owner or parameter");return matches[0];}
  static object InternalValue(Parameter p){return p.HasValue?p.Value:null;}
  static string ParameterDataType(Parameter p){return p.Definition.DataType;}
  private sealed class ParameterWriteExpectation {internal long Id,ParameterId;internal object Expected;}
  private sealed class RejectErrors {}
  static void Fields(Dictionary<string,object>a,params string[] keys){foreach(var key in a.Keys)if(!keys.Contains(key))throw new InvalidOperationException("field");}
  static object Required(Dictionary<string,object>a,string key){object v;if(!a.TryGetValue(key,out v)||v==null)throw new InvalidOperationException("required");return v;}
  static string OptionalString(Dictionary<string,object>a,string key,string fallback){return a.ContainsKey(key)?a[key] as string:fallback;}
  static object NormalizeParameterValue(Parameter p,object value,string label,bool yesNo){if(p.StorageType==StorageType.String){if(!(value is string))throw new InvalidOperationException("string");return value;}if(p.StorageType==StorageType.Double)return Convert.ToDouble(value);if(p.StorageType==StorageType.Integer)return Convert.ToInt32(value);throw new InvalidOperationException("storage");}
  static object SetParameters(Document d,Dictionary<string,object>a,List<ParameterWriteExpectation> expectations,bool guarded){var row=(Dictionary<string,object>)((object[])a["changes"])[0];long id=Convert.ToInt64(row["element_id"]),pid=Convert.ToInt64(row["parameter_id"]);Element owner;var p=ResolveInstanceParameter(d,id,pid,out owner);var old=(Dictionary<string,object>)row["expected_state"];object rawOld=old["value_internal"];if(rawOld!=null&&p.StorageType==StorageType.Double)rawOld=Convert.ToDouble(rawOld);if(rawOld!=null&&p.StorageType==StorageType.Integer)rawOld=Convert.ToInt32(rawOld);if((bool)old["has_value"]!=p.HasValue||!Object.Equals(rawOld,InternalValue(p))||(string)old["storage_type"]!=p.StorageType.ToString()||(string)old["data_type"]!=ParameterDataType(p))throw new InvalidOperationException("stale");d.SetCalls++;if(d.SetCalls==d.FailSetAt)throw new InvalidOperationException("setter failure");p.Value=row["value"];p.HasValue=true;if(d.DriftOtherAfterSet&&d.SetCalls==1)d.Elements[102].Parameters[0].Value="other-drift";expectations.Add(new ParameterWriteExpectation{Id=id,ParameterId=pid,Expected=p.Value});return null;}
  static void VerifyParameterWrites(Document d,List<ParameterWriteExpectation> items){foreach(var x in items){Element owner;var p=ResolveInstanceParameter(d,x.Id,x.ParameterId,out owner);if(!p.HasValue||!Object.Equals(p.Value,x.Expected))throw new InvalidOperationException("write drift");}}

 }
